/* Portail patient (web & mobile) */
(function () {
  const N = Nacre, D = N.D, S = N.S; const { icon, fmt, esc, avatar, badge, stBadge, toast, modal, formData } = N.ui;
  const root = document.getElementById('portal');
  const store = { get: k => { try { return sessionStorage.getItem(k); } catch (e) { return null; } }, set: (k, v) => { try { v == null ? sessionStorage.removeItem(k) : sessionStorage.setItem(k, v); } catch (e) { } } };
  let pid = store.get('nacre.portal.pid'); let tab = 'accueil';
  const P = () => N.patient(pid);
  const auditP = (action, target) => S.audit.unshift({ at: D.stamp(), user: N.pname(P()) + ' (portail)', action, target, ip: 'web' });

  /* ---------- Connexion ---------- */
  function login() {
    root.innerHTML = `<div style="min-height:100vh;display:grid;place-items:center;padding:20px;background:radial-gradient(circle at 80% 0,rgba(44,107,203,.12),transparent 50%),radial-gradient(circle at 0 100%,rgba(94,159,141,.12),transparent 50%),#FBFBFA">
      <div class="card" style="width:100%;max-width:420px;border-radius:22px;box-shadow:var(--shadow-lg)"><div class="card-body" style="padding:32px">
        <div class="brand-mark" style="width:48px;height:48px;border-radius:14px;margin-bottom:18px">${icon('tooth').replace('<svg', '<svg style="width:24px;height:24px"')}</div>
        <h1 class="serif" style="font-size:28px;color:var(--navy);font-weight:500">Mon espace patient</h1><p class="muted mt-4">${esc(S.settings.group)}</p>
        <div id="lstep" class="mt-24"><div class="field"><label>Numéro de mobile</label><input class="input" id="lphone" value="${N.patient('p1').phone}"></div><button class="btn primary mt-16" style="width:100%;height:44px" id="lsend">Recevoir un code par SMS</button></div>
        <div class="divider"></div><div class="xs muted mb-8">Démo — ouvrir le portail de :</div><div class="chips">${['p1', 'p12', 'p14', 'p15'].map(id => `<button class="chip" data-demo="${id}">${esc(N.pname(id))}</button>`).join('')}</div>
        <p class="xs faint mt-16">${icon('lock').replace('<svg', '<svg style="width:11px;height:11px;display:inline;vertical-align:-1px"')} Connexion sécurisée par code à usage unique. Vos données de santé sont chiffrées.</p>
      </div></div></div>`;
    const enter = id => { pid = id; store.set('nacre.portal.pid', id); auditP('Connexion portail patient', 'Code SMS'); N.save(); tab = 'accueil'; render(); };
    root.querySelectorAll('[data-demo]').forEach(b => b.onclick = () => enter(b.dataset.demo));
    root.querySelector('#lsend').onclick = () => {
      const ph = root.querySelector('#lphone').value.replace(/\D/g, ''); const p = S.patients.find(x => x.phone.replace(/\D/g, '') === ph);
      if (!p) return toast('Aucun dossier associé à ce numéro', 'alert');
      root.querySelector('#lstep').innerHTML = `<div class="field"><label>Code reçu par SMS</label><input class="input" id="lcode" inputmode="numeric" maxlength="6" placeholder="• • • • • •" style="letter-spacing:.4em;font-size:18px;text-align:center"></div><p class="xs muted mt-8">Code envoyé au ${p.phone.slice(0, 2)} •• •• ${p.phone.slice(-5)} · démo : saisissez 6 chiffres quelconques</p><button class="btn primary mt-16" style="width:100%;height:44px" id="lok">Se connecter</button>`;
      root.querySelector('#lok').onclick = () => { if (root.querySelector('#lcode').value.replace(/\D/g, '').length !== 6) return toast('Le code comporte 6 chiffres', 'alert'); enter(p.id); };
    };
  }

  /* ---------- Structure ---------- */
  const TABS = [['accueil', 'Accueil', 'home'], ['rdv', 'Rendez-vous', 'calendar'], ['plan', 'Mon traitement', 'clipboard'], ['documents', 'Documents', 'folder'], ['factures', 'Factures & paiements', 'wallet'], ['messages', 'Messages', 'message'], ['profil', 'Préférences', 'settings']];
  const MOB = ['accueil', 'rdv', 'documents', 'factures', 'messages'];
  function render() {
    if (!pid || !P()) return login();
    const p = P(); const unread = S.messages.filter(m => m.patient === pid && m.dir === 'out' && !m.seen).length;
    root.innerHTML = `<div class="portal"><aside class="p-side"><div class="row" style="gap:10px;padding:4px 8px 18px"><span class="brand-mark">${icon('tooth')}</span><div><b style="font-family:var(--serif);font-size:15px;color:var(--navy);font-weight:500">${esc(S.settings.group)}</b><div class="xs muted">Espace patient</div></div></div>
      <nav class="p-nav">${TABS.map(([k, l, ic]) => `<a href="javascript:void 0" data-tab="${k}" class="${tab === k ? 'on' : ''}">${icon(ic)}${l}${k === 'messages' && unread ? `<span class="dotn">${unread}</span>` : ''}</a>`).join('')}</nav>
      <div style="margin-top:auto" class="card"><div class="card-body row">${avatar(p, 'sm')}<div class="grow" style="min-width:0"><b class="small truncate" style="display:block">${esc(N.pname(p))}</b><a href="javascript:void 0" class="xs" data-logout>Se déconnecter</a></div></div></div></aside>
      <main class="p-main" id="pm"></main>
      <nav class="p-tabs">${TABS.filter(t => MOB.includes(t[0])).map(([k, l, ic]) => `<a href="javascript:void 0" data-tab="${k}" class="${tab === k ? 'on' : ''}">${icon(ic)}${l.split(' ')[0]}</a>`).join('')}</nav></div>`;
    root.querySelectorAll('[data-tab]').forEach(a => a.onclick = () => { tab = a.dataset.tab; render(); window.scrollTo(0, 0); });
    root.querySelector('[data-logout]').onclick = () => { store.set('nacre.portal.pid', null); pid = null; render(); };
    const pm = root.querySelector('#pm'); pm.innerHTML = VIEWS[tab](p); (MOUNT[tab] || (() => { }))(pm, p); N.ui.tipBind(pm);
  }
  const head = (t, s = '') => `<div class="mb-16"><h1 class="serif" style="font-size:26px;color:var(--navy);font-weight:500">${t}</h1>${s ? `<p class="muted mt-4">${s}</p>` : ''}</div>`;
  const upcoming = p => S.appts.filter(a => a.patient === p.id && (a.date > D.todayYmd() || (a.date === D.todayYmd() && a.start >= D.hm(D.nowMin()))) && ['confirme', 'attente'].includes(a.status)).sort((a, b) => (a.date + a.start).localeCompare(b.date + b.start));
  const apptCard = (a, actions = true) => { const d = N.staff(a.dentist); const t = S.types[a.type]; const h = D.diffDays(D.todayYmd(), a.date) * 24 + (D.min(a.start) - D.nowMin()) / 60;
    return `<div class="card" data-ap="${a.id}"><div class="card-body row wrap" style="gap:14px"><div style="width:60px;text-align:center;border-radius:12px;background:${t.color}14;padding:8px 0;flex:none"><div class="xs" style="color:${t.color};font-weight:600;text-transform:uppercase">${fmt.dow(a.date)}</div><div style="font-size:22px;font-weight:600">${D.parse(a.date).getDate()}</div><div class="xs muted">${fmt.MSHORT[D.parse(a.date).getMonth()]}</div></div>
      <div class="grow" style="min-width:180px"><b>${t.label} · ${fmt.hShort(a.start)}</b><div class="small muted">${esc(N.name(d))} · ${esc(N.clinic(a.clinic).name)}</div><div class="mt-4">${stBadge(a.status)}</div></div>
      ${actions ? `<div class="row wrap gap-6">${a.status === 'attente' ? `<button class="btn sm primary" data-conf>${icon('check')}Confirmer</button>` : ''}<button class="btn sm" data-move ${h < 24 ? 'disabled title="Moins de 24h : contactez le cabinet"' : ''}>${icon('repeat')}Modifier</button><button class="btn sm danger" data-cancel ${h < 24 ? 'disabled' : ''}>Annuler</button></div>` : ''}</div></div>`; };

  /* ---------- Vues ---------- */
  const VIEWS = {
    accueil(p) {
      const na = upcoming(p)[0]; const b = N.patientBalance(p.id); const plan = S.plans.find(x => x.patient === p.id && x.status !== 'termine'); const q = S.quotes.find(x => x.patient === p.id && x.status === 'envoye');
      const notifs = S.messages.filter(m => m.patient === p.id && m.dir === 'out').sort((a, b) => b.at.localeCompare(a.at)).slice(0, 4);
      return `<div class="hello"><div style="position:relative;z-index:1"><div style="opacity:.75">Bonjour</div><h1 class="serif" style="font-size:30px;font-weight:500">${esc(p.first)}</h1>
        ${na ? `<div style="margin-top:18px;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.14);border-radius:16px;padding:16px" class="row wrap between"><div><div class="xs" style="opacity:.7;letter-spacing:.08em">PROCHAIN RENDEZ-VOUS</div><b style="font-size:18px">${fmt.dateLong(na.date).replace(/^./, c => c.toUpperCase())} · ${fmt.hShort(na.start)}</b><div style="opacity:.8" class="small">${S.types[na.type].label} avec ${esc(N.name(N.staff(na.dentist)))}</div></div>${na.status === 'attente' ? `<button class="btn gold" data-confhome="${na.id}">${icon('check')}Confirmer ma présence</button>` : `<span class="badge" style="background:rgba(255,255,255,.15);color:#fff">✓ Confirmé</span>`}</div>` : `<p style="opacity:.8" class="mt-8">Aucun rendez-vous à venir.</p>`}</div></div>
      <div class="qa mt-16"><a href="reserver.html?patient=${p.id}"><span class="ic tone-blue">${icon('calendar')}</span>Prendre rendez-vous</a><button data-go="documents"><span class="ic tone-violet">${icon('download')}</span>Mes ordonnances</button><button data-go="factures"><span class="ic tone-gold">${icon('card')}</span>Payer en ligne</button><button data-go="messages"><span class="ic tone-teal">${icon('message')}</span>Contacter le cabinet</button></div>
      ${q ? `<div class="card mt-16" style="border-color:var(--primary-100);background:var(--primary-50)"><div class="card-body row wrap between"><div class="row">${icon('file').replace('<svg', '<svg style="width:22px;height:22px;color:var(--primary)"')}<div><b>Un devis vous attend</b><div class="small muted">${q.number} · ${fmt.money(N.Paper.quoteTotals(q).total)}</div></div></div><button class="btn primary sm" data-go="plan">Consulter & accepter</button></div></div>` : ''}
      <div class="grid g2 mt-16">
        ${plan ? `<div class="card"><div class="card-head"><h3>Mon traitement</h3><a class="small" href="javascript:void 0" data-go="plan">Détails</a></div><div class="card-body">${planSummary(plan)}</div></div>` : ''}
        <div class="card"><div class="card-head"><h3>Mon compte</h3></div><div class="card-body"><div class="row between"><span class="muted">Total des soins</span><b>${fmt.money(b.total)}</b></div><div class="row between mt-8"><span class="muted">Réglé</span><b style="color:var(--success)">${fmt.money(b.paid)}</b></div><div class="progress sage mt-8"><i style="width:${b.total ? b.paid / b.total * 100 : 0}%"></i></div><div class="row between mt-12"><span>Reste à régler</span><b style="font-size:18px;color:${b.due > 0 ? 'var(--danger)' : 'inherit'}">${fmt.money(b.due)}</b></div>${b.due > 0 ? `<button class="btn primary sm mt-12" data-go="factures">${icon('card')}Payer en ligne</button>` : ''}</div></div>
      </div>
      <div class="card mt-16"><div class="card-head"><h3>Notifications & rappels</h3></div><div class="card-body"><div class="list">${notifs.map(m => `<div class="li"><span class="avatar sm" style="background:var(--bg-2);color:var(--muted)">${icon(m.channel === 'email' ? 'mail' : m.channel === 'whatsapp' ? 'whatsapp' : m.channel === 'chat' ? 'message' : 'bell').replace('<svg', '<svg style="width:14px"')}</span><div class="grow" style="min-width:0"><div class="small">${esc(m.text)}</div><div class="xs faint">${fmt.ago(m.at)}</div></div></div>`).join('') || '<div class="small muted">Aucune notification</div>'}</div></div></div>`;
    },
    rdv(p) {
      const up = upcoming(p); const past = S.appts.filter(a => a.patient === p.id && !up.includes(a)).sort((a, b) => b.date.localeCompare(a.date)).slice(0, 10);
      return head('Mes rendez-vous', 'Modification et annulation gratuites jusqu’à 24h avant.') + `<a class="btn primary mb-16" href="reserver.html?patient=${p.id}">${icon('plus')}Prendre un nouveau rendez-vous</a>
        <h3 class="small muted mb-8" style="text-transform:uppercase;letter-spacing:.08em">À venir</h3><div class="col gap-16">${up.map(a => apptCard(a)).join('') || '<div class="card card-pad muted small">Aucun rendez-vous à venir.</div>'}</div>
        <h3 class="small muted mt-24 mb-8" style="text-transform:uppercase;letter-spacing:.08em">Historique</h3><div class="card"><div class="card-body"><div class="list">${past.map(a => `<div class="li"><div class="grow"><div class="t">${S.types[a.type].label}</div><div class="s">${fmt.dateLong(a.date)} · ${a.start} · ${esc(N.name(N.staff(a.dentist)))}</div></div>${stBadge(a.status)}</div>`).join('')}</div></div></div>`;
    },
    plan(p) {
      const plans = S.plans.filter(x => x.patient === p.id); const quotes = S.quotes.filter(q => q.patient === p.id && q.status !== 'brouillon');
      const ST = { propose: ['Proposé', 'tone-gray'], accepte: ['Accepté', 'tone-violet'], planifie: ['Planifié', 'st-confirme'], encours: ['En cours', 'st-encours'], termine: ['Réalisé', 'st-termine'] };
      return head('Mon plan de traitement', 'Suivez l’avancement de vos soins et vos devis.') +
        (quotes.length ? `<div class="card mb-16"><div class="card-head"><h3>Mes devis</h3></div><div class="card-body"><div class="list">${quotes.map(q => `<div class="li"><div class="grow"><div class="t">${q.number}</div><div class="s">${fmt.date(q.date)} · ${fmt.money(N.Paper.quoteTotals(q).total)}${q.status === 'accepte' ? ' · signé le ' + fmt.date(q.acceptedAt) : ''}</div></div><button class="btn sm" data-qv="${q.id}">${icon('eye')}Voir</button>${q.status === 'envoye' ? `<button class="btn sm primary" data-qa="${q.id}">${icon('signature')}Accepter en ligne</button>` : badge(q.status === 'accepte' ? 'Accepté' : q.status === 'refuse' ? 'Refusé' : 'Expiré', q.status === 'accepte' ? 'st-termine' : 'st-annule')}</div>`).join('')}</div></div></div>` : '') +
        (plans.map(pl => { const tot = pl.items.reduce((s, i) => s + i.price, 0), paid = pl.items.reduce((s, i) => s + (i.paid || 0), 0);
          return `<div class="card mb-16"><div class="card-head"><div><h3>${esc(pl.title)}</h3><div class="sub">${esc(N.name(N.staff(pl.dentist)))}</div></div></div><div class="card-body">${planSummary(pl)}<div class="timeline mt-16">${pl.items.map(i => `<div class="tl-item"><span class="tl-dot" style="${i.status === 'termine' ? 'background:var(--success);border-color:var(--success)' : ''}">${i.status === 'termine' ? `<span style="color:#fff;font-size:10px">✓</span>` : '<i></i>'}</span><div class="row between wrap"><div><b style="font-weight:500">${esc(i.label)}</b>${i.tooth && i.tooth !== '—' ? ` <span class="tag">Dent ${esc(i.tooth)}</span>` : ''}<div class="xs muted">${i.done ? 'Réalisé le ' + fmt.date(i.done) : i.planned ? 'Prévu le ' + fmt.date(i.planned) : 'À planifier'}</div></div><div class="right">${badge(ST[i.status][0], ST[i.status][1])}<div class="xs muted mt-4">${fmt.money(i.price)}</div></div></div></div>`).join('')}</div>
            <div class="grid g3 mt-16" style="gap:8px"><div class="mini-card" style="padding:12px;border:1px solid var(--line);border-radius:12px"><div class="xs muted">Total traitement</div><b>${fmt.money(tot)}</b></div><div style="padding:12px;border-radius:12px;background:var(--success-50)"><div class="xs muted">Payé</div><b style="color:var(--success)">${fmt.money(paid)}</b></div><div style="padding:12px;border-radius:12px;background:var(--danger-50)"><div class="xs muted">Reste</div><b style="color:var(--danger)">${fmt.money(tot - paid)}</b></div></div></div></div>`; }).join('') || '<div class="card card-pad muted">Aucun plan de traitement en cours.</div>');
    },
    documents(p) {
      const docs = S.docs.filter(d => d.patient === p.id && (d.shared || d.fromPortal)); const rx = S.rx.filter(r => r.patient === p.id); const ba = S.ba.filter(b => b.patient === p.id && b.visibility === 'patient');
      return head('Mes documents', 'Ordonnances, comptes rendus et documents partagés par le cabinet.') + `
        <div class="card mb-16"><div class="card-head"><h3>Ordonnances</h3></div><div class="card-body"><div class="list">${rx.map(r => `<div class="li"><span class="avatar sm" style="background:var(--violet-50);color:var(--violet)">${icon('pill').replace('<svg', '<svg style="width:14px"')}</span><div class="grow"><div class="t">Ordonnance du ${fmt.date(r.date)}</div><div class="s">${esc(r.items.map(i => i.drug).join(' · '))}</div></div><button class="btn sm" data-rx="${r.id}">${icon('download')}PDF</button></div>`).join('') || '<div class="small muted">Aucune ordonnance</div>'}</div></div></div>
        <div class="card mb-16"><div class="card-head"><h3>Documents partagés</h3></div><div class="card-body"><div class="media-grid">${docs.map(d => `<div class="media" data-doc="${d.id}"><div class="thumb">${N.ui.media(d)}${d.fromPortal ? '<span class="lock">Envoyé par vous</span>' : ''}</div><div class="meta"><b class="truncate">${esc(d.title)}</b><div class="xs muted">${fmt.date(d.date)}</div></div></div>`).join('') || '<div class="small muted">Aucun document partagé pour le moment.</div>'}</div></div></div>
        ${ba.length ? `<div class="card mb-16"><div class="card-head"><h3>Avant / Après</h3></div><div class="card-body">${ba.map(b => `<b>${esc(b.title)}</b><div class="ba mt-8" data-ba><div class="ba-img">${N.ui.smile(b.shade[0], 3, b.crowd)}</div><div class="ba-img ba-after">${N.ui.smile(b.shade[1], 3)}</div><div class="ba-handle"></div></div>`).join('')}</div></div>` : ''}
        <div class="card"><div class="card-head"><h3>Envoyer un document au cabinet</h3></div><div class="card-body"><label class="upload" id="pup">${icon('upload').replace('<svg', '<svg style="width:26px;height:26px;margin:0 auto 6px"')}<b>Ajouter un fichier</b><div class="xs">Radiographie d’un autre cabinet, résultats d’analyses, attestation de mutuelle… (JPG, PNG, PDF)</div><input type="file" hidden accept="image/*,application/pdf"></label></div></div>`;
    },
    factures(p) {
      const inv = S.invoices.filter(i => i.patient === p.id).sort((a, b) => b.date.localeCompare(a.date)); const pays = S.payments.filter(x => x.patient === p.id).sort((a, b) => b.date.localeCompare(a.date)); const b = N.patientBalance(p.id);
      return head('Factures & paiements') + `<div class="grid g3 mb-16"><div class="card card-pad"><div class="xs muted">Total des soins</div><b style="font-size:20px">${fmt.money(b.total)}</b></div><div class="card card-pad"><div class="xs muted">Réglé</div><b style="font-size:20px;color:var(--success)">${fmt.money(b.paid)}</b></div><div class="card card-pad"><div class="xs muted">Reste à régler</div><b style="font-size:20px;color:${b.due > 0 ? 'var(--danger)' : 'inherit'}">${fmt.money(b.due)}</b></div></div>
        <div class="card mb-16"><div class="card-head"><h3>Mes factures</h3></div><div class="table-wrap"><table class="table responsive"><thead><tr><th>Facture</th><th>Date</th><th class="num">Montant</th><th class="num">Reste</th><th>Statut</th><th></th></tr></thead><tbody>${inv.map(i => { const st = N.ui.INV_ST[N.invoiceStatus(i)]; const due = N.invoiceTotal(i) - N.invoicePaid(i); return `<tr><td data-l="Facture"><b style="font-weight:500">${i.number}</b><div class="xs muted">${esc(i.items.map(x => x.label).join(', '))}</div></td><td data-l="Date">${fmt.date(i.date)}</td><td data-l="Montant" class="num">${fmt.money(N.invoiceTotal(i))}</td><td data-l="Reste" class="num">${fmt.money(due)}</td><td data-l="Statut">${badge(st[0], st[1])}</td><td><div class="row gap-4">${due > 0 ? `<button class="btn xs primary" data-payinv="${i.id}">Payer</button>` : ''}<button class="btn xs" data-inv="${i.id}">${icon('download')}</button></div></td></tr>`; }).join('')}</tbody></table></div></div>
        <div class="card"><div class="card-head"><h3>Historique des paiements</h3></div><div class="card-body"><div class="list">${pays.map(x => `<div class="li"><div class="grow"><div class="t">${fmt.money(x.amount)}</div><div class="s">${fmt.date(x.date)} · ${N.ui.METHOD[x.method]}${x.kind === 'acompte' ? ' · acompte' : ''}</div></div>${badge(x.amount < 0 ? 'Remboursement' : 'Reçu', x.amount < 0 ? 'st-noshow' : 'st-termine')}</div>`).join('') || '<div class="small muted">Aucun paiement</div>'}</div></div></div>`;
    },
    messages(p) {
      S.messages.filter(m => m.patient === p.id && m.dir === 'out').forEach(m => m.seen = true); N.save();
      const ms = S.messages.filter(m => m.patient === p.id).sort((a, b) => a.at.localeCompare(b.at));
      return head('Messagerie sécurisée', 'Échangez avec l’équipe du cabinet. Pour une urgence, appelez le ' + N.clinic(p.clinic).phone + '.') + `<div class="card" style="overflow:hidden"><div class="chat-body" id="pchat" style="height:min(56vh,520px)">${ms.map(m => `<div class="msg ${m.dir === 'in' ? 'out' : 'in'}">${esc(m.text)}<div class="mt">${m.dir === 'in' ? 'Vous' : m.auto ? 'Message automatique' : esc(S.settings.group)} · ${fmt.rel(m.at.slice(0, 10))} ${fmt.time(m.at)}</div></div>`).join('')}</div><div class="chat-compose"><div class="row"><textarea class="textarea" id="pmsg" placeholder="Écrire au cabinet…" style="min-height:48px;height:48px"></textarea><button class="btn primary" id="psend" style="height:48px">${icon('send')}</button></div><div class="xs faint">${icon('lock').replace('<svg', '<svg style="width:11px;height:11px;display:inline;vertical-align:-1px"')} Messagerie chiffrée. Réponse sous 24h ouvrées.</div></div></div>`;
    },
    profil(p) {
      return head('Préférences', 'Choisissez comment recevoir vos rappels.') + `<div class="card mb-16"><div class="card-body col" style="gap:16px">${[['sms', 'Rappels par SMS', 'smartphone'], ['whatsapp', 'Rappels par WhatsApp', 'whatsapp'], ['email', 'Confirmations par email', 'mail'], ['photos', 'Autoriser le partage de mes photos avant/après avec moi', 'image']].map(([k, l, ic]) => `<div class="row between"><div class="row">${icon(ic).replace('<svg', '<svg style="width:18px;color:var(--muted)"')}<span>${l}</span></div><label class="switch"><input type="checkbox" data-pref="${k}" ${p.consent[k] ? 'checked' : ''}><span></span></label></div>`).join('')}<div class="row between"><div class="row">${icon('bell').replace('<svg', '<svg style="width:18px;color:var(--muted)"')}<span>Notifications mobiles (application)</span></div><label class="switch"><input type="checkbox" checked><span></span></label></div></div></div>
        <div class="card"><div class="card-head"><h3>Mes informations</h3></div><div class="card-body"><dl class="kv"><dt>Nom</dt><dd>${esc(N.pname(p))}</dd><dt>Téléphone</dt><dd>${p.phone}</dd><dt>Email</dt><dd>${esc(p.email)}</dd><dt>Adresse</dt><dd>${esc(p.address)}</dd><dt>N° de dossier</dt><dd>${p.fileNo}</dd></dl><p class="xs muted mt-12">Pour modifier ces informations ou exercer vos droits d’accès et de rectification, écrivez au cabinet via la messagerie.</p></div></div>`;
    }
  };
  function planSummary(pl) { const n = pl.items.length, d = pl.items.filter(i => i.status === 'termine').length; const tot = pl.items.reduce((s, i) => s + i.price, 0), paid = pl.items.reduce((s, i) => s + (i.paid || 0), 0); return `<div class="row between small"><span>${d} / ${n} étapes réalisées</span><b>${Math.round(d / n * 100)} %</b></div><div class="progress mt-8" style="height:8px"><i style="width:${d / n * 100}%"></i></div><div class="row between xs muted mt-8"><span>Total ${fmt.money(tot)}</span><span>Reste ${fmt.money(tot - paid)}</span></div>`; }

  /* ---------- Interactions ---------- */
  function reschedule(a) {
    const days = []; let d = D.addYmd(D.todayYmd(), 1); while (days.length < 14) { if (D.parse(d).getDay() !== 0) days.push(d); d = D.addYmd(d, 1); }
    let sel = null, time = null;
    const free = date => { const out = []; const dow = D.parse(date).getDay(); const end = dow === 6 ? D.min('13:00') : D.min('18:30'); for (let m = D.min('08:30'); m + a.dur <= end; m += 30) { if (m < D.min('14:00') && m + a.dur > D.min('12:30')) continue; if (!S.appts.some(x => x.id !== a.id && x.dentist === a.dentist && x.date === date && !['annule', 'noshow'].includes(x.status) && D.min(x.start) < m + a.dur && m < D.min(x.start) + x.dur)) out.push(D.hm(m)); } return out; };
    modal({ title: 'Modifier mon rendez-vous', size: 'lg', body: `<p class="small muted mb-12">${S.types[a.type].label} avec ${esc(N.name(N.staff(a.dentist)))}</p><div class="days" id="rdays">${days.map(y => `<div class="day ${free(y).length ? '' : 'off'}" data-d="${y}"><div class="dw">${fmt.dow(y)}</div><div class="dd">${D.parse(y).getDate()}</div><div class="dc">${free(y).length} créneaux</div></div>`).join('')}</div><div id="rslots" class="mt-16 slots"></div>`, foot: `<button class="btn" data-close>Annuler</button><button class="btn primary" data-ok disabled>Confirmer le changement</button>`,
      onMount: m => {
        m.querySelectorAll('[data-d]').forEach(x => x.onclick = () => { sel = x.dataset.d; time = null; m.querySelectorAll('[data-d]').forEach(y => y.classList.toggle('on', y === x)); m.querySelector('#rslots').innerHTML = free(sel).map(t => `<button class="slot" data-t="${t}">${t}</button>`).join(''); m.querySelector('[data-ok]').disabled = true; m.querySelectorAll('[data-t]').forEach(b => b.onclick = () => { time = b.dataset.t; m.querySelectorAll('[data-t]').forEach(y => y.classList.toggle('on', y === b)); m.querySelector('[data-ok]').disabled = false; }); });
        m.querySelector('[data-ok]').onclick = () => { a.date = sel; a.start = time; a.moved = true; a.status = 'confirme'; S.messages.push({ id: N.uid('m'), patient: pid, dir: 'out', channel: 'sms', text: `Votre rendez-vous a bien été déplacé au ${fmt.dateLong(sel)} à ${fmt.hShort(time)}.`, at: D.stamp(), auto: true, status: 'envoye' }); N.notify({ kind: 'booking', title: 'Rendez-vous modifié par le patient', text: `${N.pname(P())} → ${fmt.dayMonth(sel)} à ${time}`, link: '#/agenda' }); auditP('Rendez-vous déplacé (portail)', fmt.date(sel) + ' ' + time); N.save(); m.close(); render(); toast('Rendez-vous déplacé · confirmation envoyée', 'check'); };
      } });
  }
  function payOnline(inv) {
    const due = N.invoiceTotal(inv) - N.invoicePaid(inv);
    modal({ title: 'Paiement en ligne', body: `<div class="center"><div class="xs muted">Facture ${inv.number}</div><div class="serif" style="font-size:38px;color:var(--navy)">${fmt.money(due)}</div></div><div class="field mt-16"><label>Montant à régler</label><input class="input" type="number" id="pamt" min="50" max="${due}" value="${due}"></div><div class="card mt-16" style="background:var(--surface-2)"><div class="card-body small row top">${icon('lock').replace('<svg', '<svg style="width:18px;height:18px;color:var(--success);flex:none"')}<span>Vous allez être redirigé vers la <b>passerelle de paiement sécurisée</b> de la banque (3-D Secure). Vos coordonnées bancaires ne sont jamais stockées par le cabinet.<br><span class="muted">Démo : le paiement est simulé.</span></span></div></div>`, foot: `<button class="btn" data-close>Annuler</button><button class="btn primary" data-ok>${icon('card')}Continuer vers le paiement</button>`,
      onMount: m => m.querySelector('[data-ok]').onclick = () => { const amt = Math.min(due, Math.max(1, +m.querySelector('#pamt').value)); m.querySelector('.modal-body').innerHTML = `<div class="center" style="padding:30px"><div class="typing"><i></i><i></i><i></i></div><p class="muted mt-12">Connexion à la passerelle sécurisée…</p></div>`; m.querySelector('.modal-foot').remove();
        setTimeout(() => { S.payments.push({ id: N.uid('pay'), invoice: inv.id, patient: pid, clinic: P().clinic, date: D.todayYmd(), amount: amt, method: 'en_ligne', kind: amt < due ? 'acompte' : 'paiement', ref: 'Portail patient' }); N.notify({ kind: 'pay', title: 'Paiement en ligne reçu', text: `${N.pname(P())} — ${fmt.money(amt)} (${inv.number})`, link: '#/paiements' }); auditP('Paiement en ligne', inv.number + ' — ' + fmt.money(amt)); N.save(); m.querySelector('.modal-body').innerHTML = `<div class="center" style="padding:20px"><div class="success-mark">${icon('check')}</div><h3 class="serif" style="font-size:22px;color:var(--navy)">Paiement accepté</h3><p class="muted mt-8">${fmt.money(amt)} réglés. Un reçu vous a été envoyé par email.</p><button class="btn primary mt-16" data-close>Fermer</button></div>`; m.querySelector('[data-close]').onclick = () => { m.close(); render(); }; }, 1400); } });
  }
  const MOUNT = {
    accueil(pm) { pm.querySelectorAll('[data-go]').forEach(b => b.onclick = () => { tab = b.dataset.go; render(); }); const c = pm.querySelector('[data-confhome]'); if (c) c.onclick = () => confirmAppt(S.appts.find(a => a.id === c.dataset.confhome)); },
    rdv(pm) {
      pm.querySelectorAll('[data-ap]').forEach(card => { const a = S.appts.find(x => x.id === card.dataset.ap);
        const cf = card.querySelector('[data-conf]'); if (cf) cf.onclick = () => confirmAppt(a);
        const mv = card.querySelector('[data-move]'); if (mv) mv.onclick = () => reschedule(a);
        const cn = card.querySelector('[data-cancel]'); if (cn) cn.onclick = async () => { if (!(await N.ui.confirmBox('Annuler ce rendez-vous ?', `${S.types[a.type].label} du ${fmt.dateLong(a.date)} à ${fmt.hShort(a.start)}. Le créneau sera libéré pour un autre patient.`, 'Annuler le rendez-vous', true))) return; a.status = 'annule'; N.notify({ kind: 'alert', title: 'Annulation par le patient', text: `${N.pname(P())} — ${fmt.dayMonth(a.date)} ${a.start}`, link: '#/agenda' }); auditP('Rendez-vous annulé (portail)', fmt.date(a.date) + ' ' + a.start); N.save(); render(); toast('Rendez-vous annulé', 'check'); }; });
    },
    plan(pm) {
      pm.querySelectorAll('[data-qv]').forEach(b => b.onclick = () => { const q = S.quotes.find(x => x.id === b.dataset.qv); modal({ title: 'Devis ' + q.number, size: 'lg', body: N.Paper.quote(q), foot: `<button class="btn" data-p>${icon('download')}Télécharger le PDF</button>`, onMount: m => m.querySelector('[data-p]').onclick = () => N.Paper.print(N.Paper.quote(q)) }); });
      pm.querySelectorAll('[data-qa]').forEach(b => b.onclick = () => { const q = S.quotes.find(x => x.id === b.dataset.qa); const p = P();
        modal({ title: 'Accepter le devis ' + q.number, body: `<div class="card" style="background:var(--surface-2)"><div class="card-body"><div class="row between"><span class="muted">Montant total</span><b style="font-size:20px">${fmt.money(N.Paper.quoteTotals(q).total)}</b></div><div class="small muted mt-8">${esc(q.conditions)}</div></div></div><div class="field mt-16"><label>Signature — saisissez votre nom complet</label><input class="input" id="sig" placeholder="${esc(N.pname(p))}" style="font-family:var(--serif);font-size:18px"></div><label class="check mt-12 small"><input type="checkbox" id="sigok"> J’ai pris connaissance du devis et des conditions, et je donne mon accord pour les soins proposés.</label>`, foot: `<button class="btn" data-close>Annuler</button><button class="btn primary" data-ok>${icon('signature')}Signer et accepter</button>`,
          onMount: m => m.querySelector('[data-ok]').onclick = () => { const s = m.querySelector('#sig').value.trim(); if (s.length < 3 || !m.querySelector('#sigok').checked) return toast('Signature et accord requis', 'alert'); q.status = 'accepte'; q.acceptedAt = D.todayYmd(); q.signature = s; N.notify({ kind: 'alert', title: 'Devis accepté en ligne', text: `${N.pname(p)} a signé le devis ${q.number} (${fmt.money(N.Paper.quoteTotals(q).total)}).`, link: '#/devis/' + q.id }); auditP('Devis accepté en ligne (signature électronique)', q.number); N.save(); m.close(); render(); toast('Devis accepté — merci ! Le cabinet va planifier vos soins.', 'check'); } }); });
    },
    documents(pm) {
      pm.querySelectorAll('[data-rx]').forEach(b => b.onclick = () => { auditP('Téléchargement ordonnance', ''); N.save(); N.Paper.print(N.Paper.prescription(S.rx.find(r => r.id === b.dataset.rx))); });
      pm.querySelectorAll('[data-doc]').forEach(el => el.onclick = () => { const d = S.docs.find(x => x.id === el.dataset.doc); modal({ title: esc(d.title), size: 'lg', body: `<div class="viewer" style="height:min(60vh,480px)"><div class="stage">${N.ui.media(d)}</div></div>` }); });
      pm.querySelectorAll('[data-ba]').forEach(ba => { const after = ba.querySelector('.ba-after'), h = ba.querySelector('.ba-handle'); const set = x => { const r = ba.getBoundingClientRect(); const pc = Math.min(100, Math.max(0, (x - r.left) / r.width * 100)); after.style.clipPath = `inset(0 0 0 ${pc}%)`; h.style.left = pc + '%'; }; let on = false; ba.onpointerdown = e => { on = true; ba.setPointerCapture(e.pointerId); set(e.clientX); }; ba.onpointermove = e => on && set(e.clientX); ba.onpointerup = () => on = false; });
      const up = pm.querySelector('#pup input'); up.onchange = () => { const f = up.files[0]; if (!f) return; const add = src => { S.docs.unshift({ id: N.uid('doc'), patient: pid, kind: f.type.startsWith('image/') ? 'upload' : 'pdf', src, title: f.name.replace(/\.[^.]+$/, ''), date: D.todayYmd(), cat: f.type.startsWith('image/') ? 'photo' : 'pdf', seed: 1, fromPortal: true, reviewed: false }); N.notify({ kind: 'msg', title: 'Document reçu via le portail', text: `${N.pname(P())} a envoyé « ${f.name} ».`, link: '#/radiographies' }); auditP('Document envoyé (portail)', f.name); try { N.save(); } catch (e) { } render(); toast('Document envoyé au cabinet', 'upload'); }; if (f.type.startsWith('image/') && f.size < 1.5e6) { const r = new FileReader(); r.onload = () => add(r.result); r.readAsDataURL(f); } else add(f.type.startsWith('image/') ? URL.createObjectURL(f) : ''); };
    },
    factures(pm) {
      pm.querySelectorAll('[data-payinv]').forEach(b => b.onclick = () => payOnline(S.invoices.find(i => i.id === b.dataset.payinv)));
      pm.querySelectorAll('[data-inv]').forEach(b => b.onclick = () => N.Paper.print(N.Paper.invoice(S.invoices.find(i => i.id === b.dataset.inv))));
    },
    messages(pm, p) {
      const c = pm.querySelector('#pchat'); c.scrollTop = c.scrollHeight;
      const send = () => { const t = pm.querySelector('#pmsg').value.trim(); if (!t) return; S.messages.push({ id: N.uid('m'), patient: pid, dir: 'in', channel: 'chat', text: t, at: D.stamp(), auto: false, status: 'non_lu' }); N.notify({ kind: 'msg', title: 'Nouveau message patient', text: `${N.pname(p)} : « ${t.slice(0, 60)} »`, link: '#/communication/' + pid }); N.save(); render(); };
      pm.querySelector('#psend').onclick = send; pm.querySelector('#pmsg').onkeydown = e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send(); } };
    },
    profil(pm, p) { pm.querySelectorAll('[data-pref]').forEach(i => i.onchange = () => { p.consent[i.dataset.pref] = i.checked; auditP('Préférence de communication modifiée', i.dataset.pref + ' → ' + (i.checked ? 'oui' : 'non')); N.save(); toast('Préférence enregistrée'); }); }
  };
  function confirmAppt(a) { a.status = 'confirme'; N.notify({ kind: 'booking', title: 'Présence confirmée', text: `${N.pname(P())} a confirmé son RDV du ${fmt.dayMonth(a.date)} à ${a.start}.`, link: '#/agenda' }); auditP('Confirmation de présence', fmt.date(a.date) + ' ' + a.start); N.save(); render(); toast('Merci, votre présence est confirmée', 'check'); }

  render();
})();
